export const blocksIce = (world: World, position: Position) =>
  getCellEntities(world, position).some(
    (entity) =>
      hasComponent(entity, NPC) || hasComponent(entity, PLAYER) || isOpaque(world, entity)
  );

export const isFreezable = (world: World, entity: TypedEntity): entity is TypedEntity<"FREEZABLE"> =>
  hasComponent(entity, FREEZABLE);

export const getFreezables = (world: World, position: Position) =>
  getCellEntities(world, position).filter((entity) =>
    isFreezable(world, entity)
  ) as TypedEntity<"POSITION" | "FREEZABLE">[];

export const isFrozen = (world: World, entity: TypedEntity) =>
  entity[FREEZABLE]?.frozen || (entity[AFFECTABLE]?.freeze ?? 0) > 0;

export const getFrozen = (world: World, position: Position) =>
  getCellEntities(world, position).filter(
    (entity) => isFreezable(world, entity) && isFrozen(world, entity)
  ) as TypedEntity<"POSITION" | "FREEZABLE">[];

export const getUnfrozen = (world: World, position: Position) =>
  getCellEntities(world, position).filter(
    (entity) => isFreezable(world, entity) && !isFrozen(world, entity)
  ) as TypedEntity<"POSITION" | "FREEZABLE">[];

export const isSliding = (world: World, entity: TypedEntity) =>
  !!entity[MOVABLE]?.momentum;

export const isActionable = (world: World, entity: TypedEntity) =>
  hasComponent(entity, MOVABLE) &&
  !isDead(world, entity) &&
  !isFrozen(world, entity) &&
  !isSliding(world, entity);

export const isControllable = (world: World, entity: TypedEntity) =>
  isActionable(world, entity) &&
  !(isInPopup(world, entity) || isShowingPopup(world, entity));

export const isInteractable = (world: World, entity: TypedEntity) =>
  isControllable(world, entity) && !isMounting(world, entity);

const frozenSprites: Record<Immersible["type"], Sprite> = {
  water: ice,
};

// swap sprites when freezing
export const freezeTerrain = (world: World, entity: TypedEntity) => {
  if (isFrozen(world, entity))
    return entity;

  requireComponent(entity, FREEZABLE).frozen = true;
  entity[SPRITE] = spriteRef(
    frozenSprites[(entity[IMMERSIBLE] as Immersible).type]
  );

  // replace water with ice terrain
  if (entity[IMMERSIBLE] && entity[TEMPO]) {
    entity[TEMPO].amount = 0;

    world.removeComponentFromEntity(
      entity as TypedEntity<"IMMERSIBLE">,
      IMMERSIBLE,
      false
    );
    const position = requireComponent(entity, POSITION);
    const { x, y } = position;
    world.metadata.gameEntity[LEVEL].cells[x][y] = "ice";
    updateWalkable(world, position);
    updateShoreline(world, position);

    // delete any liquids
    const liquids = getLiquids(world, position);
    for (const liquidEntity of liquids) {
      disposeEntity(world, liquidEntity);
    }

    // Refresh immersion and the unit sprite after the terrain changes.
    const swimmables = getSwimmables(world, position);
    for (const swimmableEntity of swimmables) {
      rerenderEntity(world, swimmableEntity);
    }
  }

  rerenderEntity(world, entity);
  return entity;
};

// swap sprites when thawing
export const thawTerrain = (world: World, entity: TypedEntity) => {
  if (!isFrozen(world, entity)) return entity;

  requireComponent(entity, FREEZABLE).frozen = false;
  entity[SPRITE] = spriteRef(waterDeep);

  // replace ice with water terrain
  if (entity[TEMPO]) {
    entity[TEMPO].amount = -4;

    addImmersible(world, entity, { type: "water", deep: true });
    const position = requireComponent(entity, POSITION);
    const { x, y } = position;
    world.metadata.gameEntity[LEVEL].cells[x][y] = "water_deep";
    updateWalkable(world, position);
    updateShoreline(world, position);

    // Refresh immersion and the unit sprite after the terrain changes.
    const swimmables = getSwimmables(world, position);
    for (const swimmableEntity of swimmables) {
      rerenderEntity(world, swimmableEntity);
    }
  }

  // create smoke
  extinguishEntity(world, entity);

  rerenderEntity(world, entity);
};

export const freezeMomentum = (
  world: World,
  entity: TypedEntity<"MOVABLE" | "POSITION">,
  orientation?: Orientation
) => {
  const freezable = getFreezables(world, entity[POSITION])[0];
  const frozen = !entity[MOVABLE].flying && freezable && isFrozen(world, freezable);
  const lockable = getLockable(world, entity[POSITION]);
  const walkthrough = lockable && lockable[LOCKABLE].type !== "gate";
  const sliding = frozen || walkthrough;

  const momentumOrientation =
    orientation || (entity[MOVABLE].momentum as Orientation | undefined);
  const targetMovable =
    momentumOrientation &&
    isWalkable(
      world,
      add(entity[POSITION], orientationPoints[momentumOrientation])
    );

  if (sliding && !entity[MOVABLE].momentum && targetMovable && orientation) {
    // let units slide
    entity[MOVABLE].momentum = orientation;
  } else if (
    (!sliding || !targetMovable) &&
    (entity[MOVABLE].momentum || !orientation)
  ) {
    // stop sliding
    entity[MOVABLE].momentum = undefined;
  }

  // freeze on ice
  if (frozen && entity[AFFECTABLE] && targetMovable) {
    if (entity[AFFECTABLE].freeze === 1 && entity[SEQUENCABLE]?.states.freeze) {
      // extend sequence rather than retriggering
      entity[SEQUENCABLE].states.freeze.elapsed = 0;
    }
    entity[AFFECTABLE].freeze = Math.max(entity[AFFECTABLE].freeze, 1);
  }

  // ensure suspendable references keep on sliding
  const movableReference = world.assertByIdAndComponents(
    entity[MOVABLE].reference,
    [REFERENCE, RENDERABLE]
  );

  if (movableReference === world.metadata.gameEntity) return;

  if (
    entity[MOVABLE].momentum &&
    movableReference[REFERENCE].suspensionCounter === 0 &&
    (entity[PLAYER] || entity[DISPLACABLE])
  ) {
    movableReference[REFERENCE].suspensionCounter = -1;
  } else if (
    (entity[PLAYER] || entity[DISPLACABLE]) &&
    !entity[MOVABLE].momentum &&
    entity[MOVABLE].orientations.length === 0
  ) {
    movableReference[REFERENCE].suspensionCounter = 0;
  }
};

export const isSnowy = (world: World, position: Position) =>
  getCellEntities(world, position).some(
    (entity) => entity[COVERABLE]?.type === "snow"
  );

// Visit cell centers nearest the fire first, using the displayed character proportions.
const heatOffsets: Position[] = [];
const heatHalfWidths = [5, 5, 3, 1];
const distance = ({ x, y }: Position) => Math.hypot(x * aspectRatio, y);
for (let y = 1 - heatHalfWidths.length; y < heatHalfWidths.length; y++) {
  const halfWidth = heatHalfWidths[Math.abs(y)];
  for (let x = -halfWidth; x <= halfWidth; x++) heatOffsets.push({ x, y });
}
heatOffsets.sort((a, b) => distance(a) - distance(b));

export const isCampfireWarm = (world: World, position: Position) =>
  heatOffsets.some((offset) =>
    getCellEntities(world, add(position, offset)).some(
      (entity) =>
        entity[BURNABLE]?.eternal &&
        entity[BURNABLE].burning &&
        !entity[BURNABLE].simmer
    )
  );

export const meltCell = (world: World, position: Position) => {
  let melted = false;
  const cell = getCellEntities(world, position);
  for (const entity of cell) {
    if (entity[COVERABLE]?.type === "snow") {
      // Thawing the ice beneath snow already emits smoke.
      if (!melted && !cell.some((terrain) => terrain[FREEZABLE]?.frozen)) {
        extinguishEntity(world, entity);
      }
      disposeEntity(world, entity);
    } else if (entity[FREEZABLE]?.frozen) thawTerrain(world, entity);
    else continue;
    melted = true;
  }
  return melted;
};

export const meltNearCampfire = (world: World, position: Position) =>
  heatOffsets.some((offset) => meltCell(world, add(position, offset)));

export const snowFill = 0.4;
export const coverSnow = (
  world: World,
  position: Position,
  creation = false
) => {
  // check odds and don't repeat snow
  const willFreeze = getUnfrozen(world, position).length > 0;
  if (
    isSnowy(world, position) ||
    (getTempo(world, position) !== 0 && !willFreeze) ||
    blocksIce(world, position) ||
    isCampfireWarm(world, position) ||
    getLockable(world, position) ||
    getFragment(world, position)
  )
    return;

  if (!willFreeze && !creation) {
    // ensure distributed snow fill
    let fill = 0;
    for (let offsetX = -1; offsetX <= 1; offsetX += 1) {
      for (let offsetY = -1; offsetY <= 1; offsetY += 1) {
        const delta = { x: offsetX, y: offsetY };
        const targetPosition = add(position, delta);
        if (isSnowy(world, targetPosition)) {
          fill += 1;
        }
        if (fill / 9 > snowFill) return;
      }
    }
  }

  if (!creation || willFreeze || Math.random() <= snowFill) {
    applySnow(world, position);
  }

  if (creation && willFreeze && Math.random() <= snowFill) {
    applySnow(world, position);
  }
};

export const applySnow = (world: World, position: Position) => {
  const unfrozen = getUnfrozen(world, position);
  if (unfrozen.length > 0) {
    return unfrozen.map((entity) => freezeTerrain(world, entity))[0];
  }
  const overlay = getCellEntities(world, position).some(
    (entity) =>
      entity[FREEZABLE]?.frozen ||
      entity[SPRITE]?.id === jetty.id ||
      entity[HARVESTABLE]?.resource === "rubble"
  );

  return entities.createSnow(world, {
    [CLICKABLE]: { clicked: false, player: false },
    [FOG]: {
      visibility: "hidden",
      type: overlay ? "object" : "terrain",
    },
    [COVERABLE]: { type: "snow" },
    [POSITION]: position,
    [RENDERABLE]: { generation: 0 },
    [SPRITE]: overlay ? snowCover : snow,
  });
};

export const applySnowMap = (world: World) => {
  const size = world.metadata.gameEntity[LEVEL].size;
  matrixFactory(size, size, (x, y) => {
    coverSnow(world, { x, y });
  });
};

export default function setupFreeze(world: World) {
  let referenceGenerations = -1;

  const onUpdate = (delta: number) => {
    const generation = world
      .getEntities([RENDERABLE, REFERENCE])
      .reduce((total, entity) => entity[RENDERABLE].generation + total, 0);

    if (referenceGenerations === generation) return;

    referenceGenerations = generation;

    for (const entity of world.getEntities([
      POSITION,
      AFFECTABLE,
      RENDERABLE,
      SEQUENCABLE,
    ])) {
      if (entity[AFFECTABLE].freeze === 0) continue;

      // freeze units
      if (!getSequence(world, entity, "freeze")) {
        createSequence<"freeze", FreezeSequence>(
          world,
          entity,
          "freeze",
          "unitFreeze",
          { total: entity[AFFECTABLE].freeze }
        );

        if (!entity[MOVABLE]?.momentum) {
          queueMessage(world, entity, {
            line: createText("FROZEN", colors.aqua),
            orientation: "up",
            fast: false,
            delay: 0,
          });
        }
      }

      // prevent movements
      if (entity[MOVABLE]) {
        const entityReference = world.assertByIdAndComponents(
          entity[MOVABLE].reference,
          [RENDERABLE]
        )[RENDERABLE].generation;

        entity[MOVABLE].lastInteraction = entityReference;
        entity[MOVABLE].pendingOrientation = undefined;
      }
    }

    // remove snow
    for (const entity of world.getEntities([CLICKABLE, COVERABLE, POSITION])) {
      if (entity[COVERABLE].type === "snow" && entity[CLICKABLE].clicked) {
        play(world, entity, "snow");
        disposeEntity(world, entity);
      }
    }
  };

  return { onUpdate };
}
